from typing import List

def calculate_min_cost(n: int, s: str, c: List[int]) -> int:
    zo = [0]
    oz = [0]

    for i in range(n):
        if i % 2:
            if s[i] == '1':
                oz.append(oz[-1] + c[i])
                zo.append(zo[-1])
            else:
                zo.append(zo[-1] + c[i])
                oz.append(oz[-1])
        else:
            if s[i] == '1':
                zo.append(zo[-1] + c[i])
                oz.append(oz[-1])
            else:
                oz.append(oz[-1] + c[i])
                zo.append(zo[-1])

    min_cost = float('inf')
    for i in range(1, n):
        cost_to_flip = min(c[i-1], c[i])
        cost_to_alternate = min(oz[i-1] + zo[-1] - zo[i], zo[i-1] + oz[-1] - oz[i])
        min_cost = min(min_cost, cost_to_flip + cost_to_alternate)

    return min_cost
